const upsertSourceConnection = `-- name: UpsertSourceConnection :one
INSERT INTO
  source_connections (
    user_id,
    kind,
    client_id,
    credentials,
    synced_through
  )
VALUES
  ($1, $2, $3, $4, $5)
ON CONFLICT (user_id, kind) DO UPDATE
SET
  client_id = EXCLUDED.client_id,
  credentials = EXCLUDED.credentials,
  last_error = '',
  needs_reconnect = FALSE
RETURNING
  id, user_id, kind, client_id, credentials, synced_through, last_synced_at, last_error, needs_reconnect, created_at
`

type UpsertSourceConnectionParams struct {
	UserID        int32              `json:"user_id"`
	Kind          string             `json:"kind"`
	ClientID      int32              `json:"client_id"`
	Credentials   string             `json:"credentials"`
	SyncedThrough pgtype.Timestamptz `json:"synced_through"`
}

// Connecting again replaces the tokens and clears the fault, and carries on from where the syncs had got to.
func (q *Queries) UpsertSourceConnection(ctx context.Context, arg *UpsertSourceConnectionParams) (*SourceConnection, error) {
	row := q.db.QueryRow(ctx, upsertSourceConnection,
		arg.UserID,
		arg.Kind,
		arg.ClientID,
		arg.Credentials,
		arg.SyncedThrough,
	)
	var i SourceConnection
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Kind,
		&i.ClientID,
		&i.Credentials,
		&i.SyncedThrough,
		&i.LastSyncedAt,
		&i.LastError,
		&i.NeedsReconnect,
		&i.CreatedAt,
	)
	return &i, err
}
